<?php
require __DIR__.'/auth.php'; require_login(); require __DIR__.'/db.php';

use App\Repositories\ActaVisualizacionRepository;
use App\Services\ActaVisualizacionService;

function h($v): string { return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8'); }
$repo=new ActaVisualizacionRepository($pdo); $service=new ActaVisualizacionService($repo);
$id=(int)($_GET['id']??$_POST['id']??0); $embed=(int)($_GET['embed']??$_POST['embed']??0)===1;
$row=$id?$repo->find($id):null; if($id&&!$row){http_response_code(404);exit('Acta no encontrada');}
$accidenteId=(int)($row['accidente_id']??$_GET['accidente_id']??$_POST['accidente_id']??0); if($accidenteId<=0){http_response_code(400);exit('Falta accidente_id');}
$ctx=$service->context($accidenteId); $error='';
$selectedParticipants=array_fill_keys(array_map(fn($p)=>$p['fuente'].':'.$p['fuente_id'],$row['participantes']??[]),true);
$disks=$row['discos']??[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{$id=$service->save($id?:null,$accidenteId,$_POST);if($embed){echo '<script>window.parent.postMessage({type:"acta.saved"},"*")</script>';exit;}header('Location: accidente_vista_tabs.php?accidente_id='.$accidenteId.'&tab=documentos&subtab=actas');exit;}catch(Throwable $e){$error=$e->getMessage();$selectedParticipants=array_fill_keys((array)($_POST['participantes']??[]),true);$disks=(array)($_POST['discos']??[]);}
}
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Acta de visualizacion</title><style>
.office{border:2px solid #0ea5e9;border-radius:14px;margin-top:12px;background:#f0f9ff;overflow:hidden}.office summary{cursor:pointer;padding:14px 16px;font-weight:800;color:#075985}.office-body{padding:0 16px 16px}.responses{margin:10px 0;padding:10px 14px;border-left:4px solid #22c55e;background:#f0fdf4;border-radius:8px}.office-media{margin-top:10px}.empty{padding:16px;border:1px dashed #94a3b8;border-radius:10px;text-align:center}.office .description{grid-template-columns:155px minmax(260px,1fr) auto}.capture-box{display:none}.disk-title,.file-title{cursor:pointer;user-select:none}.disk-title::before,.file-title::before{content:'▾ ';font-size:13px}.disk.collapsed .disk-title::before,.file.collapsed .file-title::before{content:'▸ '}.disk.collapsed>.grid,.disk.collapsed>.head:not(.disk-head),.disk.collapsed>.files{display:none}.file.collapsed>.file-fields,.file.collapsed>.head:not(.file-head),.file.collapsed>.descriptions,.file.collapsed>.description-actions{display:none}
:root{--bg:#f4f6fa;--p:#fff;--line:#d9e0ea;--text:#172033;--muted:#667085;--blue:#245ea8}*{box-sizing:border-box}body{margin:0;padding:18px;background:var(--bg);font:14px system-ui;color:var(--text)}.wrap{max-width:1180px;margin:auto}.panel{background:var(--p);border:1px solid var(--line);border-radius:14px;padding:18px;margin-bottom:14px}.head,.row,.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.head{justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.full{grid-column:1/-1}label{display:block;font-weight:700;margin-bottom:5px}input,textarea,select{width:100%;padding:10px;border:1px solid var(--line);border-radius:8px;background:#fff}.btn{padding:9px 12px;border:1px solid var(--line);border-radius:8px;background:#fff;text-decoration:none;color:var(--text);font-weight:700;cursor:pointer}.primary{background:var(--blue);color:#fff}.check-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.check{display:flex;gap:8px;padding:9px;border:1px solid var(--line);border-radius:8px}.check input{width:auto}.muted{color:var(--muted);font-size:12px}.disk{--disk-color:#2563eb;--disk-soft:#eff6ff;border:2px solid var(--disk-color);border-left-width:8px;border-radius:16px;padding:16px;margin-top:18px;background:linear-gradient(135deg,var(--disk-soft),#fff 38%);box-shadow:0 10px 24px rgba(15,23,42,.08)}.disk-head{padding-bottom:12px;border-bottom:2px solid var(--disk-color)}.disk-title{font-size:18px;color:var(--disk-color)}.files{display:grid;gap:14px;margin-top:12px}.file{--file-color:var(--disk-color);border:2px solid var(--file-color);border-radius:13px;padding:13px;background:#fff;box-shadow:0 6px 16px rgba(15,23,42,.06)}.file-head{margin-bottom:10px;padding-bottom:8px;border-bottom:1px solid color-mix(in srgb,var(--file-color) 45%,white)}.file-title{color:var(--file-color);font-size:15px}.file-fields{display:grid;grid-template-columns:2fr repeat(3,1fr);gap:8px}.descriptions{display:grid;gap:10px;margin-top:12px}.description{--moment-color:var(--file-color);display:grid;grid-template-columns:155px minmax(260px,1fr) 250px auto;gap:10px;padding:12px;border:2px solid var(--moment-color);border-left-width:7px;background:#fff;border-radius:11px;box-shadow:0 4px 12px rgba(15,23,42,.05)}.description:nth-child(even){background:#f8fafc}.moment-title{display:block;color:var(--moment-color);font-size:13px;margin-bottom:8px}.description-actions{display:flex;justify-content:flex-end;margin-top:10px;padding-top:10px;border-top:1px dashed color-mix(in srgb,var(--file-color) 45%,white)}.add-description{color:var(--file-color);border-color:var(--file-color);background:#fff}.capture-box{border:1px dashed var(--moment-color);border-radius:8px;padding:7px;min-height:75px;background:#fff}.capture-box img{display:block;max-width:100%;max-height:160px;margin-top:6px;border-radius:6px}.remove-description,.remove-file,.remove-disk{color:#9f1239;border-color:#fecdd3;background:#fff7f8}.error{padding:10px;background:#fff1f2;color:#9f1239;border-radius:8px;margin-bottom:12px}@media(max-width:850px){.grid,.check-grid,.file-fields,.description{grid-template-columns:1fr}.description-actions{justify-content:stretch}.description-actions .btn{width:100%}}
</style></head><body><main class="wrap"><div class="panel head"><div><h1 style="margin:0">Acta de visualizacion</h1><div class="muted">Caso #<?= $accidenteId ?> · <?= h($ctx['accident']['registro_sidpol']) ?></div></div><?php if($embed):?><button class="btn" onclick="parent.postMessage({type:'acta.close'},'*')">Cerrar</button><?php else:?><a class="btn" href="accidente_vista_tabs.php?accidente_id=<?=$accidenteId?>&tab=documentos&subtab=actas">Volver</a><?php endif?></div>
<?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="accidente_id" value="<?=$accidenteId?>"><input type="hidden" name="embed" value="<?=$embed?1:0?>">
<section class="panel grid"><div><label>Fecha</label><input type="date" name="fecha_visualizacion" value="<?=h($_POST['fecha_visualizacion']??$row['fecha_visualizacion']??date('Y-m-d'))?>" required></div><div><label>Hora de inicio</label><input type="time" name="hora_inicio" value="<?=h(substr((string)($_POST['hora_inicio']??$row['hora_inicio']??date('H:i')),0,5))?>" required></div><div><label>Fiscal</label><input value="<?=h($ctx['accident']['fiscal']?:'No registrado')?>" readonly></div><div><label>Fiscalia</label><input value="<?=h($ctx['accident']['fiscalia']?:'No registrada')?>" readonly></div><div class="full"><label>Datos del accidente</label><textarea readonly><?=h('SIDPOL: '.$ctx['accident']['registro_sidpol']."\nFecha: ".$ctx['accident']['fecha_accidente']."\nLugar: ".$ctx['accident']['lugar']."\nReferencia: ".$ctx['accident']['referencia'])?></textarea></div></section>
<section class="panel"><h2>Personas consideradas</h2><div class="check-grid"><?php foreach($ctx['participants'] as $p):$key=$p['fuente'].':'.$p['fuente_id'];?><label class="check"><input type="checkbox" name="participantes[]" value="<?=h($key)?>" <?=isset($selectedParticipants[$key])?'checked':''?>><span><strong><?=h($p['nombre'])?></strong><br><span class="muted"><?=h($p['condicion'])?></span></span></label><?php endforeach?></div></section>
<section class="panel"><h2>Oficios de cámaras y documentos recibidos</h2><p class="muted">Solo se muestran oficios de cámaras o videovigilancia que tienen un documento recibido relacionado.</p><?php if(!$ctx['offices']):?><div class="empty">No existe todavía una coincidencia entre un oficio de cámaras y un documento recibido.</div><?php endif?><?php foreach($ctx['offices'] as $i=>$office):$roman=['I','II','III','IV','V','VI','VII','VIII','IX','X'][$i]??(string)($i+1);?><details class="office" data-office-id="<?=$office['oficio_id']?>" <?=$i===0?'open':''?>><summary><?=h($roman.'. Oficio '.($i+1).' — '.$office['titulo'])?></summary><div class="office-body"><div class="muted"><?=h($office['descripcion'])?></div><div class="responses"><strong>Documento<?=count($office['respuestas'])===1?'':'s'?> recibido<?=count($office['respuestas'])===1?'':'s'?> relacionado<?=count($office['respuestas'])===1?'':'s'?></strong><?php foreach($office['respuestas'] as $response):?><div>• <?=h($response['descripcion'])?></div><?php endforeach?></div><button type="button" class="btn add-medium">+ Agregar DISCO o USB</button><div class="office-media"></div></div></details><?php endforeach?></section>
<section class="panel grid"><div><label>Estado</label><select name="estado"><?php foreach(['Pendiente','Realizada','Anulada'] as $s):?><option <?=($_POST['estado']??$row['estado']??'Pendiente')===$s?'selected':''?>><?=$s?></option><?php endforeach?></select></div><div class="full"><label>Observaciones</label><textarea name="observaciones"><?=h($_POST['observaciones']??$row['observaciones']??'')?></textarea></div><div class="full actions" style="justify-content:flex-end"><button class="btn primary">Guardar acta</button></div></section></form></main>
<template id="disk-template"><div class="disk"><input type="hidden" data-field="oficio_id"><div class="head disk-head"><strong class="disk-title"></strong><button type="button" class="btn remove-disk">Eliminar medio</button></div><div class="grid" style="margin-top:14px"><div><label>Medio recibido</label><select data-field="tipo_medio" required><option value="">Seleccionar</option><option>DISCO</option><option>USB</option></select></div><div><label>Marca</label><input data-field="marca" required></div><div><label>Número de serie</label><input data-field="numero_serie" required></div><div><label>Capacidad</label><input data-field="capacidad" placeholder="Ej.: 16 GB, 1 TB" required></div><div class="full"><label>Características u observaciones</label><input data-field="observaciones"></div></div><div class="head" style="margin-top:14px"><strong>Archivos contenidos en este medio</strong><button type="button" class="btn add-file">+ Agregar archivo</button></div><div class="files"></div></div></template>
<template id="file-template"><div class="file"><div class="head file-head"><strong class="file-title"></strong><button type="button" class="btn remove-file">Quitar archivo</button></div><div class="file-fields"><div><label>Nombre del archivo</label><input data-file-field="nombre_archivo" required></div><div><label>Tipo</label><input data-file-field="tipo_archivo"></div><div><label>Peso</label><input data-file-field="peso"></div><div><label>Duración</label><input data-file-field="duracion"></div></div><div class="head" style="margin-top:14px"><strong>Momentos observados</strong><span class="muted">Se mostrarán en este mismo orden en el acta.</span></div><div class="descriptions"></div><div class="description-actions"><button type="button" class="btn add-description">+ Agregar descripción debajo</button></div></div></template>
<template id="description-template"><div class="description"><div><strong class="moment-title"></strong><label>Tiempo observado</label><input type="time" step="1" data-description-field="tiempo" required><div class="muted">Hora, minuto y segundo</div></div><div><label>Descripción del momento observado</label><textarea data-description-field="detalle" rows="5" required></textarea></div><button type="button" class="btn remove-description">Quitar momento</button></div></template>
<script>
const initial=<?=json_encode(array_values($disks),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const diskPalettes=[['#2563eb','#eff6ff'],['#7c3aed','#f5f3ff'],['#0f766e','#f0fdfa'],['#c2410c','#fff7ed'],['#be123c','#fff1f2'],['#0369a1','#f0f9ff']],fileColors=['#1d4ed8','#0891b2','#7c3aed','#c2410c','#be123c','#047857'],momentColors=['#2563eb','#7c3aed','#0891b2','#d97706','#be123c','#047857'];
function allDisks(){return [...document.querySelectorAll('.disk')]}
function renumber(){allDisks().forEach((d,di)=>{const palette=diskPalettes[di%diskPalettes.length],type=d.querySelector('[data-field=tipo_medio]').value||'DISCO/USB';d.style.setProperty('--disk-color',palette[0]);d.style.setProperty('--disk-soft',palette[1]);d.querySelector('.disk-title').textContent=String.fromCharCode(65+(di%26))+'. '+type+' '+(di+1);d.querySelectorAll('[data-field]').forEach(x=>x.name=`discos[${di}][${x.dataset.field}]`);[...d.querySelectorAll('.file')].forEach((f,fi)=>{const fileColor=fileColors[fi%fileColors.length];f.style.setProperty('--file-color',fileColor);f.querySelector('.file-title').textContent=String.fromCharCode(97+(fi%26))+') Archivo '+(fi+1);f.querySelectorAll('[data-file-field]').forEach(x=>x.name=`discos[${di}][archivos][${fi}][${x.dataset.fileField}]`);[...f.querySelectorAll('.description')].forEach((r,ri)=>{r.style.setProperty('--moment-color',momentColors[ri%momentColors.length]);r.querySelector('.moment-title').textContent='Momento observado '+(ri+1);r.querySelectorAll('[data-description-field]').forEach(x=>x.name=`discos[${di}][archivos][${fi}][descripciones][${ri}][${x.dataset.descriptionField}]`)})})})}
function addDescription(f,data={}){const r=document.getElementById('description-template').content.firstElementChild.cloneNode(true);r.querySelectorAll('[data-description-field]').forEach(x=>x.value=data[x.dataset.descriptionField]||'');r.querySelector('.remove-description').onclick=()=>{r.remove();renumber()};f.querySelector('.descriptions').append(r);renumber()}
function addFile(d,data={}){d.querySelectorAll('.file').forEach(x=>x.classList.add('collapsed'));const f=document.getElementById('file-template').content.firstElementChild.cloneNode(true);f.querySelectorAll('[data-file-field]').forEach(x=>x.value=data[x.dataset.fileField]||'');f.querySelector('.file-title').onclick=()=>f.classList.toggle('collapsed');f.querySelector('.remove-file').onclick=()=>{f.remove();renumber()};f.querySelector('.add-description').onclick=()=>addDescription(f);d.querySelector('.files').append(f);const moments=data.descripciones||[];if(moments.length)moments.forEach(v=>addDescription(f,v));else addDescription(f);renumber()}
function addDisk(office,data={}){office.querySelectorAll('.disk').forEach(x=>x.classList.add('collapsed'));const d=document.getElementById('disk-template').content.firstElementChild.cloneNode(true);data.oficio_id=data.oficio_id||office.dataset.officeId;d.querySelectorAll('[data-field]').forEach(x=>x.value=data[x.dataset.field]||'');d.querySelector('.disk-title').onclick=()=>d.classList.toggle('collapsed');d.querySelector('[data-field=tipo_medio]').onchange=renumber;d.querySelector('.remove-disk').onclick=()=>{d.remove();renumber()};d.querySelector('.add-file').onclick=()=>addFile(d);office.querySelector('.office-media').append(d);const files=data.archivos||[];if(files.length)files.forEach(f=>addFile(d,f));else addFile(d);office.open=true;renumber()}
document.querySelectorAll('.office').forEach(office=>office.querySelector('.add-medium').onclick=()=>addDisk(office));
initial.forEach(data=>{let office=document.querySelector(`.office[data-office-id="${Number(data.oficio_id)||0}"]`);if(!office)office=document.querySelector('.office');if(office)addDisk(office,data)});
</script></body></html>
